export function buildFeatureChecklistSummary() {
  const byStatus = {};
  for (const f of FEATURE_CHECKLIST) {
    byStatus[f.status] = (byStatus[f.status] || 0) + 1;
  }
  return { total: FEATURE_CHECKLIST.length, byStatus };
}

export default { FEATURE_CHECKLIST, buildFeatureChecklistSummary };